<?php

declare(strict_types=1);require_once __DIR__.'/../../includes/module-admin.php';$pdo=cmsAdminModuleBoot('reels');$base='/admin/reels.php';
if($_SERVER['REQUEST_METHOD']==='POST'){cmsVerifyCsrf();$a=cmsStr($_POST['action']??'save',20);$id=cmsInt($_POST['id']??0);if($a==='delete'&&$id){$s=$pdo->prepare('SELECT media_path,poster_path FROM reels WHERE id=:id');$s->execute([':id'=>$id]);$old=$s->fetch();$pdo->prepare('DELETE FROM reels WHERE id=:id')->execute([':id'=>$id]);if($old){cmsDeleteLocalUpload($old['media_path']);cmsDeleteLocalUpload($old['poster_path']);}cmsAudit('reels.delete','reels',(string)$id);cmsAdminRedirect($base,'تم الحذف.');}if($a==='toggle'&&$id){$pdo->prepare('UPDATE reels SET is_active=1-is_active WHERE id=:id')->execute([':id'=>$id]);cmsAudit('reels.toggle','reels',(string)$id);cmsAdminRedirect($base,'تم تحديث الحالة.');}
