 if($id){$s=$pdo->prepare('SELECT media_path,poster_path FROM reels WHERE id=:id');$s->execute([':id'=>$id]);$old=$s->fetch()?:['media_path'=>null,'poster_path'=>null];$mp=$media??$old['media_path'];$pp=$poster??$old['poster_path'];$q=$pdo->prepare('UPDATE reels SET title_ar=:ar,title_en=:en,media_path=:m,external_url=:u,poster_path=:p,sort_order=:s,is_active=:i WHERE id=:id');$q->execute([':ar'=>$ar?:null,':en'=>$en?:null,':m'=>$mp,':u'=>$url?:null,':p'=>$pp,':s'=>$sort,':i'=>$active,':id'=>$id]);if($media&&$old['media_path']&&$media!==$old['media_path'])cmsDeleteLocalUpload($old['media_path']);if($poster&&$old['poster_path']&&$poster!==$old['poster_path'])cmsDeleteLocalUpload($old['poster_path']);$act='reels.update';}else{$q=$pdo->prepare('INSERT INTO reels(title_ar,title_en,media_path,external_url,poster_path,sort_order,is_active) VALUES(:ar,:en,:m,:u,:p,:s,:i)');$q->execute([':ar'=>$ar?:null,':en'=>$en?:null,':m'=>$media,':u'=>$url?:null,':p'=>$poster,':s'=>$sort,':i'=>$active]);$act='reels.create';}cmsAudit($act,'reels',(string)$id);cmsAdminRedirect($base,'تم الحفظ.');}
$edit=null;if($id=cmsInt($_GET['edit']??0)){$s=$pdo->prepare('SELECT * FROM reels WHERE id=:id');$s->execute([':id'=>$id]);$edit=$s->fetch()?:null;}$rows=$pdo->query('SELECT * FROM reels ORDER BY sort_order,id')->fetchAll();cmsAdminHead('الريلز');cmsAdminSidebar('reels');cmsAdminTopbar('الريلز');?>
<div class="content"><?php if($m=cmsAdminMessage()):?><div class="alert"><?=cmsE($m)?></div><?php endif;?><div class="split"><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>العنوان</th><th>المصدر</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=cmsE((string)$r['title_ar'])?><div class="muted"><?=cmsE((string)$r['title_en'])?></div></td><td><?=$r['media_path']?'ملف محلي':'رابط خارجي'?></td><td><span class="pill <?=$r['is_active']?'ok':'bad'?>"><?=$r['is_active']?'ظاهر':'مخفي'?></span></td><td><div class="actions"><a class="btn" href="?edit=<?=$r['id']?>">تعديل</a><form method="post"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" name="action" value="toggle">إظهار/إخفاء</button><button class="btn danger" name="action" value="delete" onclick="return confirm('حذف؟')">حذف</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><section class="card"><h2><?=$edit?'تعديل':'إضافة Reel'?></h2><form method="post" enctype="multipart/form-data"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label class="field"><span>العنوان AR</span><input name="title_ar" value="<?=cmsE((string)($edit['title_ar']??''))?>"></label><label class="field"><span>Title EN</span><input name="title_en" value="<?=cmsE((string)($edit['title_en']??''))?>"></label><label class="field"><span>رابط خارجي</span><input name="external_url" value="<?=cmsE((string)($edit['external_url']??''))?>" placeholder="https://"></label><label class="field"><span>فيديو محلي</span><input type="file" name="media" accept="video/*"></label><label class="field"><span>Poster</span><input type="file" name="poster" accept="image/*"></label><div class="form-grid"><label class="field"><span>الترتيب</span><input type="number" name="sort_order" value="<?=intval($edit['sort_order']??0)?>"></label><label class="module-row"><span>ظاهر</span><input class="check" type="checkbox" name="is_active" value="1" <?=cmsChecked($edit['is_active']??1)?>></label></div><div class="actions" style="margin-top:16px"><button class="btn primary">حفظ</button><?php if($edit):?><a class="btn" href="<?=$base?>">إلغاء</a><?php endif;?></div></form></section></div></div><?php cmsAdminEnd();
